css:
.app {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-rows: auto 1fr;
  grid-template-areas:
    "top top"
    "side main";
  min-height: 360px;
}

.top {
  grid-area: top;
  padding: 12px 16px;
  background: #18181b;
  color: #fafafa;
}

.side {
  grid-area: side;
  position: sticky;
  top: 0;
  align-self: start;
  padding: 12px;
  background: #27272a;
  color: #fafafa;
}

.menu {
  margin: 0;
  padding-left: 16px;
}

.main {
  grid-area: main;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
  padding: 16px;
}

.card {
  min-height: 96px;
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

@media (max-width: 520px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-areas:
      "top"
      "side"
      "main";
  }
}
